type Aturan = (harga: number) => number;

function terapkan(daftar: number[], aturan: Aturan): number[] {
  return daftar.map(aturan);
}
function buatDiskon(persen: number): Aturan {
  return (h) => h - (h * persen) / 100;
}
const harga = [20000, 50000];
console.log(terapkan(harga, buatDiskon(10)));
console.log(terapkan(harga, (h) => h + 2000));

