type Validator = (teks: string) => string | null;
const wajibIsi: Validator = (t) => (t.trim() === "" ? "Wajib diisi" : null);
const minimal3: Validator = (t) => (t.length < 3 ? "Minimal 3 huruf" : null);
function periksa(teks: string, aturan: Validator[]): string {
  for (const a of aturan) {
    const pesan = a(teks);
    if (pesan !== null) return pesan;
  }
  return "OK";
}
const semua = [wajibIsi, minimal3];
console.log(periksa("", semua));
console.log(periksa("ab", semua));
console.log(periksa("Rina", semua));
